#!/usr/bin/env bash
# apply-notification-routing.sh
#
# SUPERSEDES apply-contractor-guide.sh — this carries everything that one did,
# plus notification routing. Run ONLY this one.
#
#   1. Contractor onboarding guide (page + settings link + dashboard card,
#      welcome email, URGENT job-alert subject, one-email-per-job)
#   2. Every notification is now a working link — taps land on the exact tab
#      (and job) the notification is talking about.
#
# Nothing here sends email. DB + edge functions are already live.

set -euo pipefail
cd ~/freddy-fixit

# A crashed git from an earlier run can leave this behind and block every commit.
rm -f .git/index.lock

echo "Getting the latest code..."
git fetch origin
git checkout main
git reset --hard origin/main

decode() { # decode <path> <<< base64
  mkdir -p "$(dirname "$1")"
  base64 --decode > "$1"
}

echo "Writing files..."
echo "  src/lib/contractorGuide.ts"
