git commit -q -m "Contractor guide + notification deep links

- Contractor onboarding guide: /contractor-guide page, settings link,
  dismissible dashboard card, welcome-email CTA
- New-job alert email subject is now URGENT, and only one email per job
- Every notification now opens the exact tab (and job) it mentions,
  instead of dropping the user on the dashboard root"
git push origin main

